left = input().split()
right = input().split()

def gini(labels):
    n = len(labels)
    counts = {}
    for x in labels:
        counts[x] = counts.get(x, 0) + 1
    return 1 - sum((c / n) ** 2 for c in counts.values())

n = len(left) + len(right)
gl, gr = gini(left), gini(right)
print(f'left {gl:.3f}')
print(f'right {gr:.3f}')
print(f'weighted {len(left) / n * gl + len(right) / n * gr:.3f}')

