def read():
    return list(map(float, input().split()))

def mse(y, p):
    return sum((a - b) ** 2 for a, b in zip(y, p)) / len(y)

ya, pa, yb, pb = read(), read(), read(), read()
tr = mse(ya, pa)
te = mse(yb, pb)
print(f'train {tr:.2f}')
print(f'test {te:.2f}')
print('overfitting' if te > 2 * tr else 'ok')
